function hasCycle(head) {
  // Fast moves 2x; if it laps slow, there is a cycle.
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

