function findKthLargest(nums, k) {
  // Heap intuition: maintain the top-k; sort is the simple JS stand-in.
  return [...nums].sort((a, b) => b - a)[k - 1];
}

function lastStoneWeight(stones) {
  // Re-sort acts as a max-heap pop each round.
  const arr = [...stones];
  while (arr.length > 1) {
    arr.sort((a, b) => b - a);
    const y = arr.shift();
    const x = arr.shift();
    if (y !== x) arr.unshift(y - x);
  }
  return arr.length ? arr[0] : 0;
}

function numIslands(grid) {
  // Mutate the grid to mark visited cells.
  if (!grid.length) return 0;
  const rows = grid.length, cols = grid[0].length;
  let count = 0;
  const dfs = (r, c) => {
    if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] !== '1') return;
    grid[r][c] = '0';
    dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1);
  };
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === '1') { count++; dfs(r, c); }
    }
  }
  return count;
}

function shortestPath(graph, start, end) {
  // Queue entries carry the distance traveled so far.
  const queue = [[start, 0]];
  const visited = new Set([start]);
  while (queue.length) {
    const [node, dist] = queue.shift();
    if (node === end) return dist;
    for (const neighbor of graph[node] || []) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push([neighbor, dist + 1]);
      }
    }
  }
  return -1;
}
